mapper.select:
WITH facts AS (
), duration_distribution AS ( SELECT a.duration_ms, CUME_DIST() OVER (ORDER BY a.duration_ms) AS percentile FROM app_generation_attempt a
a.duration_ms IS NOT NULL AND a.started_at >= #{startAt}
), ttft_distribution AS ( SELECT a.ttft_ms, CUME_DIST() OVER (ORDER BY a.ttft_ms) AS percentile FROM app_generation_attempt a
a.ttft_ms IS NOT NULL AND a.started_at >= #{startAt}
) SELECT COALESCE(SUM(attempt_count), 0) AS totalAttempts, COALESCE(SUM(success_count), 0) AS successAttempts, COALESCE(SUM(failure_count), 0) AS failedAttempts, COALESCE(SUM(cancelled_count), 0) AS cancelledAttempts, COALESCE(SUM(success_count) / NULLIF(SUM(attempt_count), 0), 0) AS successRate, COALESCE(SUM(prompt_tokens), 0) AS promptTokens, COALESCE(SUM(completion_tokens), 0) AS completionTokens, COALESCE(SUM(estimated_token_attempts), 0) AS estimatedTokenAttempts, COALESCE(SUM(total_cost_usd), 0) AS totalCostUsd, COALESCE(SUM(priced_attempts), 0) AS pricedAttempts, COALESCE(SUM(unpriced_attempts), 0) AS unpricedAttempts, COALESCE(SUM(estimated_cost_attempts), 0) AS estimatedCostAttempts, COALESCE(SUM(partial_cost_attempts), 0) AS partialCostAttempts, COALESCE(ROUND(SUM(duration_sum_ms) / NULLIF(SUM(duration_sample_count), 0)), 0) AS avgDurationMs, (SELECT MIN(duration_ms) FROM duration_distribution WHERE percentile >= 0.95) AS p95DurationMs, COALESCE(ROUND(SUM(ttft_sum_ms) / NULLIF(SUM(ttft_sample_count), 0)), 0) AS avgTtftMs, (SELECT MIN(ttft_ms) FROM ttft_distribution WHERE percentile >= 0.95) AS p95TtftMs FROM facts

WITH facts AS (
), ranked AS ( SELECT a.provider_key, a.duration_ms, CUME_DIST() OVER (PARTITION BY a.provider_key ORDER BY a.duration_ms) AS percentile FROM app_generation_attempt a
a.duration_ms IS NOT NULL AND a.started_at >= #{startAt}
) SELECT f.provider_key AS providerKey, SUM(f.attempt_count) AS attempts, SUM(f.success_count) AS successCount, SUM(f.failure_count) AS failureCount, COALESCE(SUM(f.success_count) / NULLIF(SUM(f.attempt_count), 0), 0) AS successRate, SUM(f.fallback_attempts) AS fallbackAttempts, COALESCE(ROUND(SUM(f.duration_sum_ms) / NULLIF(SUM(f.duration_sample_count), 0)), 0) AS avgDurationMs, (SELECT MIN(r.duration_ms) FROM ranked r WHERE r.provider_key = f.provider_key AND r.percentile >= 0.95) AS p95DurationMs, COALESCE(ROUND(SUM(f.ttft_sum_ms) / NULLIF(SUM(f.ttft_sample_count), 0)), 0) AS avgTtftMs, COALESCE(SUM(COALESCE(f.prompt_tokens, 0) + COALESCE(f.completion_tokens, 0)), 0) AS totalTokens, COALESCE(SUM(f.total_cost_usd), 0) AS totalCostUsd FROM facts f GROUP BY f.provider_key ORDER BY attempts DESC, f.provider_key ASC
